java.util.concurrent.atomic.AtomicBoolean factoryInvoked = new java.util.concurrent.atomic.AtomicBoolean(false);
java.util.concurrent.atomic.AtomicBoolean resizerInvoked = new java.util.concurrent.atomic.AtomicBoolean(false);

net.coobird.thumbnailator.resizers.Resizer customResizer = new net.coobird.thumbnailator.resizers.Resizer() {
    @Override
    public void resize(java.awt.image.BufferedImage srcImage, java.awt.image.BufferedImage destImage) {
        resizerInvoked.set(true);
        java.awt.Graphics2D g = destImage.createGraphics();
        g.drawImage(srcImage, 0, 0, destImage.getWidth(), destImage.getHeight(), null);
        g.dispose();
    }
};

net.coobird.thumbnailator.resizers.ResizerFactory customFactory = new net.coobird.thumbnailator.resizers.ResizerFactory() {
    @Override
    public net.coobird.thumbnailator.resizers.Resizer getResizer() {
        factoryInvoked.set(true);
        return customResizer;
    }

    @Override
    public net.coobird.thumbnailator.resizers.Resizer getResizer(java.awt.Dimension originalSize, java.awt.Dimension thumbnailSize) {
        factoryInvoked.set(true);
        return customResizer;
    }
};

java.awt.image.BufferedImage result = net.coobird.thumbnailator.Thumbnails.of(sourceImage)
    .size(50, 50)
    .resizerFactory(customFactory)
    .asBufferedImage();

assert factoryInvoked.get() : "Custom ResizerFactory was not invoked by the builder";
assert resizerInvoked.get() : "Custom Resizer was not invoked during image generation";
assert result.getWidth() == 50 || result.getHeight() == 50 : "Resulting image dimensions do not match the requested size";

System.out.println("__CHECK__ resizerFactory " + factoryInvoked.get() + "-" + resizerInvoked.get());

